// Shot Lab: Wilson's safety, broken down. Data Story style over broadcast footage.
// Footage timeline (cut.mp4): 0-7 freeze before the shot | 7-13.44 the shot at 0.5x | 13.44-20.40 freeze after |
// 20.40-36.40 freeze before the shot (safer option, comparison, takeaway).
// All numbers are estimates: ball positions tracked from the broadcast frames, mapped to a 3569 x 1778 mm table,
// speeds from frame-to-frame distance, pot chances from a simple aim-error model (see the README of this edit).

const OX = 150;                                   // footage is drawn shifted right to make room for the panel
const M = (p) => [p[0] * 2 + OX, p[1] * 2];       // source pixel (640x360) -> design space
const PX = 44;                                    // panel left margin
const SEG = { slow: [7.0, 13.44], after: [13.44, 20.40], alt: [20.40, 28.4], cmp: [28.4, 33.0], take: [33.0, 36.4] };
const srcAt = (t) => 32.30 + (t - SEG.slow[0]) / 2;   // cut time -> source time in the slow-motion part

// ---------- speeds (m/s) as piecewise-linear keys in source time; repeated times are impacts ----------
const CUE_V = [[32.45, 2.05], [33.91, 1.70], [33.91, 1.46], [34.35, 1.22], [34.35, 0.98], [34.87, 0.78], [34.87, 0.62], [35.52, 0]];
const RED_V = [[33.91, 0.90], [35.45, 0]];
function pw(K, s) {
  if (s <= K[0][0]) return K[0][1];
  for (let i = 0; i < K.length - 1; i++) { const a = K[i], b = K[i + 1]; if (s >= a[0] && s < b[0]) return lerp(a[1], b[1], (s - a[0]) / (b[0] - a[0])); }
  return K[K.length - 1][1];
}
function trackAt(T, s) {
  if (s <= T[0][0]) return [T[0][1], T[0][2]];
  for (let i = 0; i < T.length - 1; i++) { const a = T[i], b = T[i + 1]; if (s <= b[0]) { const u = (s - a[0]) / Math.max(1e-6, b[0] - a[0]); return [lerp(a[1], b[1], u), lerp(a[2], b[2], u)]; } }
  const z = T[T.length - 1]; return [z[1], z[2]];
}
const CONTACT = 33.91, CUSH1 = 34.35, CUSH2 = 34.87;

// ---------- drawing helpers ----------
function panelBG(c, a = 1) {
  c.save(); c.globalAlpha = a;
  const g = c.createLinearGradient(0, 0, 470, 0); g.addColorStop(0, 'rgba(15,20,28,0.97)'); g.addColorStop(0.72, 'rgba(15,20,28,0.9)'); g.addColorStop(1, 'rgba(15,20,28,0)');
  c.fillStyle = g; c.fillRect(0, 0, 470, 720);
  const g2 = c.createRadialGradient(120, 90, 0, 120, 90, 420); g2.addColorStop(0, 'rgba(255,107,91,0.08)'); g2.addColorStop(1, 'rgba(255,107,91,0)'); c.fillStyle = g2; c.fillRect(0, 0, 470, 720);
  c.restore();
}
function footage(c, dim = 0) {
  c.fillStyle = C.bg; c.fillRect(0, 0, 1280, 720);
  if (FOOTAGE.ready()) c.drawImage(FOOTAGE.el, OX, 0, 1280, 720);
  if (dim > 0) { c.fillStyle = `rgba(15,20,28,${dim})`; c.fillRect(0, 0, 1280, 720); }
}
function srcLine(c, t) { c.save(); c.globalAlpha = 0.95; c.font = MONO(16); c.fillStyle = '#7d8796'; c.fillText('Estimates · ball tracking from the broadcast feed + pot-probability model', PX, 702); c.restore(); }
function tagS(c, s, x, y, t0, t, col = C.coral) { c.save(); c.globalAlpha *= span(t, t0, t0 + 0.3); c.font = MONO(20, 600); c.fillStyle = col; c.letterSpacing = '3px'; c.fillText(s, x, y); c.restore(); }
function fadeOut(c, t, t1, d = 0.35) { c.globalAlpha *= 1 - span(t, t1 - d, t1); }
function poly(c, pts) { c.beginPath(); pts.forEach((p, i) => (i ? c.lineTo(p[0], p[1]) : c.moveTo(p[0], p[1]))); }
function partial(pts, f) {                         // first fraction f of a polyline (by length)
  const L = [0]; for (let i = 1; i < pts.length; i++) L.push(L[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  const want = L[L.length - 1] * clamp(f), out = [pts[0]];
  for (let i = 1; i < pts.length; i++) { if (L[i] <= want) { out.push(pts[i]); continue; } const u = (want - L[i - 1]) / (L[i] - L[i - 1]); out.push([lerp(pts[i - 1][0], pts[i][0], u), lerp(pts[i - 1][1], pts[i][1], u)]); break; }
  return out;
}
function ballRing(c, p, r, col, a = 1, w = 3) { c.save(); c.globalAlpha *= a; c.strokeStyle = col; c.lineWidth = w; c.shadowColor = col; c.shadowBlur = 14; c.beginPath(); c.arc(p[0], p[1], r, 0, 7); c.stroke(); c.restore(); }
function label(c, s, x, y, col = C.ink, a = 1, align = 'left', size = 18) {
  c.save(); c.globalAlpha *= a; c.font = MONO(size, 600); const w = textW(c, s, MONO(size, 600));
  const bx = align === 'right' ? x - w - 20 : align === 'center' ? x - w / 2 - 10 : x;
  c.fillStyle = 'rgba(15,20,28,0.86)'; rr(c, bx, y - size - 8, w + 20, size + 18, 8); c.fill();
  c.fillStyle = col; c.fillText(s, bx + 10, y + 1); c.restore();
}
// glowing dashed/solid shot line
function shotLine(c, a, b, f, col, o = {}) {
  if (f <= 0) return; const e = [lerp(a[0], b[0], clamp(f)), lerp(a[1], b[1], clamp(f))];
  c.save(); c.strokeStyle = col; c.lineWidth = o.w || 3.5; c.lineCap = 'round'; if (o.dash) c.setLineDash(o.dash); c.shadowColor = col; c.shadowBlur = o.glow == null ? 10 : o.glow;
  c.beginPath(); c.moveTo(a[0], a[1]); c.lineTo(e[0], e[1]); c.stroke(); c.restore();
}
function potDiagram(c, P, t0, t, col, t1) {
  const cue = M(P.cue), gh = M(P.ghost), ob = M(P.obj), pk = M(P.pocket);
  c.save(); if (t1) fadeOut(c, t, t1);
  shotLine(c, cue, gh, ez.inout3(span(t, t0, t0 + 0.6)), C.ink, { dash: [10, 9], w: 2.5, glow: 0 });
  if (t > t0 + 0.5) ballRing(c, gh, 11, C.ink, span(t, t0 + 0.5, t0 + 0.8), 2);
  shotLine(c, ob, pk, ez.inout3(span(t, t0 + 0.7, t0 + 1.2)), col, { w: 4 });
  if (t > t0 + 1.1) { const s = ez.back(span(t, t0 + 1.1, t0 + 1.45), 2.2); c.save(); c.translate(pk[0], pk[1]); c.scale(s, s); ballRing(c, [0, 0], 17, col, 1, 3.5); c.restore(); }
  ballRing(c, ob, 13, col, span(t, t0 + 0.6, t0 + 0.9), 3);
  c.restore();
}
// big percentage with a bar under it
function bigPct(c, x, y, val, t0, t, col, cap, sub) {
  const k = ez.outExpo(span(t, t0, t0 + 1.1)), n = Math.round(val * k);
  c.save(); c.globalAlpha *= span(t, t0, t0 + 0.2);
  c.font = MONO(18, 600); c.fillStyle = C.mute; c.letterSpacing = '2px'; c.fillText(cap, x, y - 128); c.letterSpacing = '0px';
  c.font = HEAD(124); c.fillStyle = col; c.shadowColor = col; c.shadowBlur = 26 * (1 - span(t, t0 + 1.0, t0 + 1.8)); const w = textW(c, String(n), HEAD(124)); c.fillText(String(n), x - 6, y); c.shadowBlur = 0;
  c.font = HEAD(56, 700); c.fillText('%', x + w, y);
  c.fillStyle = 'rgba(238,241,245,0.12)'; rr(c, x, y + 22, 330, 10, 5); c.fill(); c.fillStyle = col; rr(c, x, y + 22, 330 * val / 100 * k, 10, 5); c.fill();
  if (sub) { c.globalAlpha *= span(t, t0 + 0.6, t0 + 1.0); c.font = MONO(18); c.fillStyle = C.ink; c.fillText(sub, x, y + 64); }
  c.restore();
}
function headLines(c, lines, x, y, t0, t, size = 56, gap = 64, col = C.ink) {
  lines.forEach((ln, i) => riseLine(c, ln.split(' ').map((w, j) => [w, t0 + i * 0.18 + j * 0.06]), x, y + i * gap, HEAD(size), col, t));
}

// ---------- beat 1: what was on ----------
function beatOptions(c, t) {
  footage(c, 0.12 * span(t, 0, 0.6)); panelBG(c, span(t, 0, 0.5));
  tagS(c, 'SHOT LAB · WILSON TO PLAY', PX, 70, 0.15, t);
  c.save(); fadeOut(c, t, 4.3); headLines(c, ['What was', 'on?'], PX, 140, 0.35, t); c.restore();
  potDiagram(c, DATA.potOn, 1.1, t, C.sand, 6.0);
  c.save(); fadeOut(c, t, 4.3); bigPct(c, PX, 420, 32, 2.0, t, C.sand, 'POT CHANCE · BEST RED', 'long red · bottom-left · 2.3 m'); c.restore();
  if (t > 1.7) { const p = M(DATA.potOn.obj); label(c, 'best pot on', p[0] - 24, p[1] - 22, C.sand, span(t, 1.7, 2.0) * (1 - span(t, 5.6, 6.0)), 'right'); }
  // decision
  c.save(); c.globalAlpha *= span(t, 4.2, 4.5); headLines(c, ['1 in 3.', 'He plays', 'safe.'], PX, 250, 4.35, t, 60, 70); c.restore();
  if (t > 5.4) { c.save(); c.globalAlpha *= span(t, 5.4, 5.8); c.font = MONO(20); c.fillStyle = C.mute; c.fillText('Watch the cue ball.', PX, 520); c.restore(); }
  const cb = M(DATA.potOn.cue); ballRing(c, cb, 14 + 2 * Math.sin(t * 5), C.coral, span(t, 5.6, 6.0));
}

// ---------- beat 2: the shot, live ----------
const SPK = { x: PX, y: 520, w: 340, h: 120, s0: 32.45, s1: 35.52, vmax: 2.2 };
function beatShot(c, t) {
  const s = srcAt(t); footage(c); panelBG(c);
  tagS(c, 'THE SAFETY · 0.5× SPEED', PX, 70, SEG.slow[0], t);
  // cue speed readout
  const v = s < 32.45 ? 0 : pw(CUE_V, s);
  c.save(); c.font = MONO(18, 600); c.fillStyle = C.mute; c.letterSpacing = '2px'; c.fillText('CUE BALL SPEED', PX, 128); c.letterSpacing = '0px';
  c.font = HEAD(110); c.fillStyle = C.ink; const vs = v.toFixed(2); c.fillText(vs, PX - 4, 238); c.font = MONO(26, 600); c.fillStyle = C.coral; c.fillText('m/s', PX + textW(c, vs, HEAD(110)) + 8, 238); c.restore();
  // red speed (after contact)
  if (s > CONTACT) {
    const a = span(s, CONTACT, CONTACT + 0.12), vr = pw(RED_V, s);
    c.save(); c.globalAlpha *= a; c.font = MONO(18, 600); c.fillStyle = C.mute; c.letterSpacing = '2px'; c.fillText('RED SPEED', PX, 300); c.fillText('CONTACT', PX + 200, 300); c.letterSpacing = '0px';
    c.font = HEAD(58); c.fillStyle = C.teal; c.fillText(vr.toFixed(2), PX, 362); c.fillStyle = C.sand; c.fillText('59°', PX + 200, 362);
    c.font = MONO(18); c.fillStyle = C.mute; c.fillText('m/s', PX + 4 + textW(c, vr.toFixed(2), HEAD(58)) + 6, 362); c.fillText('cut', PX + 200 + textW(c, '59°', HEAD(58)) + 8, 362); c.restore();
  }
  // sparkline of cue speed
  { const S = SPK; c.save(); c.globalAlpha *= span(t, SEG.slow[0] + 0.2, SEG.slow[0] + 0.6);
    c.font = MONO(16, 600); c.fillStyle = C.mute; c.letterSpacing = '2px'; c.fillText('SPEED OVER THE SHOT', S.x, S.y - 18); c.letterSpacing = '0px';
    c.strokeStyle = C.grid; c.lineWidth = 1; [0, 1, 2].forEach((g) => { const y = S.y + S.h - (g / S.vmax) * S.h; c.beginPath(); c.moveTo(S.x, y); c.lineTo(S.x + S.w, y); c.stroke(); c.font = MONO(14); c.fillStyle = C.faint; c.fillText(String(g), S.x + S.w + 8, y + 5); });
    const sx = (q) => S.x + (q - S.s0) / (S.s1 - S.s0) * S.w, sy = (val) => S.y + S.h - (val / S.vmax) * S.h;
    const now = clamp(s, S.s0, S.s1), pts = [];
    for (const [q, val] of CUE_V) { if (q > now) break; pts.push([sx(q), sy(val)]); }
    if (s > S.s0) pts.push([sx(now), sy(pw(CUE_V, now))]);
    if (pts.length > 1) {
      const ag = c.createLinearGradient(0, S.y, 0, S.y + S.h); ag.addColorStop(0, 'rgba(255,107,91,0.28)'); ag.addColorStop(1, 'rgba(255,107,91,0)');
      c.fillStyle = ag; c.beginPath(); c.moveTo(pts[0][0], S.y + S.h); pts.forEach((p) => c.lineTo(p[0], p[1])); c.lineTo(pts[pts.length - 1][0], S.y + S.h); c.closePath(); c.fill();
      c.strokeStyle = C.coral; c.lineWidth = 3; c.lineJoin = 'round'; poly(c, pts); c.stroke();
      [[CONTACT, 'red'], [CUSH1, 'cush'], [CUSH2, 'cush']].forEach(([q, nm]) => { if (s < q) return; const e = ez.back(span(s, q, q + 0.08), 2.4); c.save(); c.translate(sx(q), sy(pw(CUE_V, q - 1e-4))); c.scale(e, e); c.fillStyle = C.bg; c.strokeStyle = nm === 'red' ? C.sand : C.ink; c.lineWidth = 2.5; c.beginPath(); c.arc(0, 0, 6, 0, 7); c.fill(); c.stroke(); c.restore(); });
    }
    c.restore(); }
  // trail on the table
  const trail = DATA.cueTrack.filter((p) => p[0] <= s).map((p) => M([p[1], p[2]])); const head = M(trackAt(DATA.cueTrack, s));
  if (s > 32.45) { trail.push(head); c.save(); c.strokeStyle = C.coral; c.lineWidth = 5; c.lineJoin = 'round'; c.lineCap = 'round'; c.shadowColor = 'rgba(255,107,91,0.8)'; c.shadowBlur = 16; poly(c, trail); c.stroke(); c.restore(); }
  ballRing(c, head, 15, C.coral, 1, 3);
  if (s > 32.45 && s < 35.5) label(c, v.toFixed(2) + ' m/s', head[0] + 26, head[1] - 18, C.ink, 1);
  // contact flash + red trail
  if (s > CONTACT) {
    const cp = M([352, 232]), f = span(s, CONTACT, CONTACT + 0.25);
    ballRing(c, cp, 14 + 40 * f, C.sand, 1 - f, 3);
    const rt = DATA.redTrack.filter((p) => p[0] <= s).map((p) => M([p[1], p[2]])); rt.push(M(trackAt(DATA.redTrack, s)));
    c.save(); c.strokeStyle = C.teal; c.lineWidth = 4; c.lineCap = 'round'; c.shadowColor = C.teal; c.shadowBlur = 12; poly(c, rt); c.stroke(); c.restore();
    ballRing(c, rt[rt.length - 1], 12, C.teal, 1, 2.5);
    label(c, '59° cut', cp[0] - 20, cp[1] - 26, C.sand, span(s, CONTACT, CONTACT + 0.1), 'right');
  }
  [[CUSH1, [430, 292], 'cushion 1'], [CUSH2, [492, 245], 'cushion 2']].forEach(([q, p, nm]) => { if (s < q) return; const P = M(p); ballRing(c, P, 10 + 26 * span(s, q, q + 0.2), C.ink, 1 - span(s, q, q + 0.25), 2); });
}

// ---------- beat 3: the result ----------
function beatResult(c, t) {
  const a = SEG.after[0]; footage(c, 0.1 * span(t, a, a + 0.5)); panelBG(c);
  tagS(c, 'THE RESULT', PX, 70, a, t);
  headLines(c, ['Left in', 'the open.'], PX, 140, a + 0.1, t);
  const cb = M(DATA.moody.cue); ballRing(c, cb, 15 + 3 * Math.sin((t - a) * 6), C.coral, span(t, a, a + 0.3), 3);
  label(c, 'cue ball stops here', cb[0] + 24, cb[1] - 22, C.coral, span(t, a + 0.3, a + 0.6) * (1 - span(t, a + 1.6, a + 1.9)));
  potDiagram(c, DATA.moody, a + 1.6, t, C.coral);
  if (t > a + 2.6) { const p = M(DATA.moody.obj); label(c, "Moody's easy red", p[0] - 22, p[1] + 44, C.coral, span(t, a + 2.6, a + 2.9), 'right'); }
  bigPct(c, PX, 420, 96, a + 2.4, t, C.coral, "MOODY'S NEXT POT", 'red · bottom-left · 8° cut · 0.4 m');
}

// ---------- beat 4: the safer option ----------
const ALT_T = [21.7, 25.9];
const ALT_V = (f, F) => { // speed by path fraction; F = fractions at contact, cushion 1, cushion 2
  const K = [[0, 2.45], [F[0], 2.12], [F[0], 2.09], [F[1], 1.86], [F[1], 1.49], [F[2], 0.95], [F[2], 0.76], [1, 0]];
  return pw(K, f);
};
const ALT_PTS = () => DATA.alt.map(M);
const ALT_F = (() => { let L = [0]; const P = DATA.alt; for (let i = 1; i < P.length; i++) L.push(L[i - 1] + Math.hypot(P[i][0] - P[i - 1][0], P[i][1] - P[i - 1][1])); return L.slice(1, 4).map((x) => x / L[L.length - 1]); })();
function beatAlt(c, t) {
  const a = SEG.alt[0]; footage(c, 0.1); panelBG(c);
  tagS(c, 'THE SAFER OPTION', PX, 70, a, t, C.sand);
  headLines(c, ['Thinner.', 'Firmer.'], PX, 140, a + 0.1, t, 56, 64, C.ink);
  const u = span(t, ALT_T[0], ALT_T[1]), f = 1 - Math.pow(1 - u, 1.9), pts = ALT_PTS();
  // planned path faintly first
  c.save(); c.globalAlpha *= 0.35 * span(t, a + 0.5, a + 1.0); c.setLineDash([8, 10]); c.strokeStyle = C.sand; c.lineWidth = 2.5; poly(c, pts); c.stroke(); c.restore();
  const tr = partial(pts, f);
  if (u > 0) { c.save(); c.strokeStyle = C.sand; c.lineWidth = 5; c.lineJoin = 'round'; c.lineCap = 'round'; c.shadowColor = 'rgba(242,193,78,0.8)'; c.shadowBlur = 16; poly(c, tr); c.stroke(); c.restore(); }
  const head = tr[tr.length - 1], v = u <= 0 ? 0 : ALT_V(f, ALT_F);
  // ghost cue ball
  c.save(); c.globalAlpha *= span(t, a + 0.3, a + 0.6); c.fillStyle = 'rgba(255,246,220,0.92)'; c.beginPath(); c.arc(head[0], head[1], 7, 0, 7); c.fill(); c.restore();
  ballRing(c, head, 15, C.sand, span(t, a + 0.3, a + 0.6), 3);
  if (u > 0 && u < 1) label(c, v.toFixed(2) + ' m/s', head[0] + 26, head[1] - 18, C.ink);
  // red nudged
  if (f >= ALT_F[0]) { const k = ez.out3(span(f, ALT_F[0], Math.min(1, ALT_F[0] + 0.25))), r0 = M(DATA.altRed[0]), r1 = M(DATA.altRed[1]); const rp = [lerp(r0[0], r1[0], k), lerp(r0[1], r1[1], k)]; ballRing(c, rp, 12, C.teal, 1, 2.5); label(c, '≈80° · thin', r0[0] - 22, r0[1] - 24, C.sand, span(f, ALT_F[0], ALT_F[0] + 0.04), 'right'); }
  // readout
  c.save(); c.globalAlpha *= span(t, a + 0.6, a + 1.0) * (1 - span(t, ALT_T[1] + 0.2, ALT_T[1] + 0.5)); c.font = MONO(18, 600); c.fillStyle = C.mute; c.letterSpacing = '2px'; c.fillText('CUE BALL SPEED', PX, 300); c.letterSpacing = '0px';
  c.font = HEAD(84); c.fillStyle = C.ink; const vs = (u <= 0 ? 2.45 : v).toFixed(2); c.fillText(vs, PX - 3, 386); c.font = MONO(22, 600); c.fillStyle = C.sand; c.fillText('m/s', PX + textW(c, vs, HEAD(84)) + 8, 386);
  c.font = MONO(18); c.fillStyle = C.mute; c.fillText('start pace · played: 2.05', PX, 420); c.restore();
  if (t > ALT_T[1]) { const e = M(DATA.alt[DATA.alt.length - 1]); label(c, 'tight on the baulk cushion', e[0] - 26, e[1] + 52, C.sand, span(t, ALT_T[1], ALT_T[1] + 0.3), 'right'); }
  // Moody from there
  if (t > ALT_T[1] + 0.3) {
    potDiagram(c, DATA.altMoody, ALT_T[1] + 0.3, t, C.coral);
    bigPct(c, PX, 560, 23, ALT_T[1] + 0.5, t, C.sand, "MOODY'S NEXT POT", 'long red · 2.8 m · off the cushion');
  }
}

// ---------- beat 5: comparison (full screen) ----------
function cmpCardS(c, x, cap, val, col, rows, t0, t) {
  const e = ez.outExpo(span(t, t0, t0 + 0.55)); if (e <= 0) return; c.save(); c.globalAlpha *= e; c.translate(0, (1 - e) * 40);
  c.fillStyle = 'rgba(238,241,245,0.04)'; rr(c, x, 150, 490, 450, 24); c.fill(); c.strokeStyle = 'rgba(238,241,245,0.10)'; c.lineWidth = 1.5; rr(c, x, 150, 490, 450, 24); c.stroke();
  c.font = MONO(22, 600); c.fillStyle = C.mute; c.letterSpacing = '3px'; c.fillText(cap, x + 36, 204); c.letterSpacing = '0px';
  const n = Math.round(val * ez.out3(span(t, t0 + 0.1, t0 + 0.9))); c.font = HEAD(150); c.fillStyle = col; const w = textW(c, String(n), HEAD(150)); c.fillText(String(n), x + 30, 350); c.font = HEAD(64, 700); c.fillText('%', x + 34 + w, 350);
  c.font = MONO(20); c.fillStyle = C.ink; c.fillText("Moody's chance at the next pot", x + 36, 392);
  rows.forEach(([k, v2], i) => { const y = 448 + i * 46; c.globalAlpha = e * span(t, t0 + 0.5 + i * 0.12, t0 + 0.8 + i * 0.12); c.strokeStyle = C.grid; c.beginPath(); c.moveTo(x + 36, y - 30); c.lineTo(x + 454, y - 30); c.stroke(); c.font = MONO(19); c.fillStyle = C.mute; c.fillText(k, x + 36, y); c.font = MONO(19, 600); c.fillStyle = C.ink; c.textAlign = 'right'; c.fillText(v2, x + 454, y); c.textAlign = 'left'; });
  c.restore();
}
function beatCmp(c, t) {
  const a = SEG.cmp[0]; background(c, t);
  tagS(c, 'SAME TABLE · TWO SAFETIES', 80, 96, a + 0.05, t);
  cmpCardS(c, 70, 'AS PLAYED', 96, C.coral, [['start pace', '2.05 m/s'], ['contact', '59° cut'], ['cue ball ends', 'open, mid-table']], a + 0.2, t);
  cmpCardS(c, 720, 'SAFER OPTION', 23, C.sand, [['start pace', '≈2.45 m/s'], ['contact', '≈80° thin'], ['cue ball ends', 'baulk cushion']], a + 0.55, t);
  const k = span(t, a + 1.6, a + 2.3); if (k > 0) { const pop = 1 + 0.12 * Math.sin(Math.PI * span(t, a + 2.3, a + 2.55)); c.save(); c.translate(640, 330); c.scale(pop, pop); c.fillStyle = C.bg; c.beginPath(); c.arc(0, -20, 64, 0, 7); c.fill(); c.strokeStyle = C.sand; c.lineWidth = 3; c.beginPath(); c.arc(0, -20, 64, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * ez.out3(k)); c.stroke(); c.font = HEAD(52); c.textAlign = 'center'; c.fillStyle = C.sand; c.globalAlpha = Math.min(1, k * 3); c.fillText('4×', 0, -2); c.font = MONO(15, 600); c.fillStyle = C.ink; c.fillText('less risk', 0, 22); c.restore(); }
  c.save(); c.globalAlpha *= span(t, a + 2.6, a + 3.0); c.font = MONO(19); c.fillStyle = C.mute; c.textAlign = 'center'; c.fillText('Pot chance on the best pot each position leaves.', 640, 650); c.restore();
}

// ---------- beat 6: takeaway ----------
function beatTake(c, t) {
  const a = SEG.take[0]; background(c, t); const F = HEAD(88);
  riseLine(c, [['Same', a + 0.15], ['shot,', a + 0.3]], 640, 320, F, C.ink, t, { align: 'center' });
  const p = span(t, a + 0.95, a + 1.35), on = p > 0.6, b = riseLine(c, [['less', a + 0.5, on ? C.bg : C.ink], ['risk.', a + 0.65, on ? C.bg : C.ink]], 640, 430, F, C.ink, t, { align: 'center' });
  if (p > 0) { const box = { x: b[0].x, w: b[1].x + b[1].w - b[0].x, y: 430 }; pillBehind(c, box, F, p, C.sand, 18); rise(c, 'less', b[0].x, 430, F, C.bg, a + 0.5, t); rise(c, 'risk.', b[1].x, 430, F, C.bg, a + 0.65, t); }
  if (t > a + 1.5) { const e = ez.outExpo(span(t, a + 1.5, a + 2.0)); c.save(); c.globalAlpha = e; c.font = MONO(24); c.fillStyle = C.mute; c.textAlign = 'center'; c.fillText('Thinner contact, a touch more pace: cue ball back to baulk.', 640, 540 + (1 - e) * 14); c.restore(); }
}

// ---------- compositor ----------
const BEATS_S = [
  { a: 0, b: SEG.slow[0], draw: beatOptions },
  { a: SEG.slow[0], b: SEG.after[0], draw: beatShot },
  { a: SEG.after[0], b: SEG.alt[0], draw: beatResult },
  { a: SEG.alt[0], b: SEG.cmp[0], draw: beatAlt },
  { a: SEG.cmp[0], b: SEG.take[0], draw: beatCmp },
  { a: SEG.take[0], b: 36.4, draw: beatTake },
];
const LYR1 = CM.layer(1280, 720), LYR2 = CM.layer(1280, 720);
function drawBeat(L, x, t) { const g = L.getContext('2d'); g.setTransform(1, 0, 0, 1, 0, 0); g.globalAlpha = 1; g.clearRect(0, 0, 1280, 720); x.draw(g, t); return L; }
const XF = 0.4; // crossfade at beat 4->5 and 5->6 (full-screen ones); others cut on a frozen frame
function vignette(c) { const v = c.createRadialGradient(640, 360, 420, 640, 360, 880); v.addColorStop(0, 'rgba(0,0,0,0)'); v.addColorStop(1, 'rgba(0,0,0,0.28)'); c.fillStyle = v; c.fillRect(0, 0, 1280, 720); }
var EDIT = {
  D: 36.4,
  SPANS: [[0, 36.4]],
  draw(c, t) {
    const i = BEATS_S.findIndex((x) => t >= x.a && t < x.b), x = BEATS_S[Math.max(0, i)];
    const prev = BEATS_S[i - 1];
    if (prev && i >= 3 && t < x.a + XF) {
      const e = ez.inout3((t - x.a) / XF);
      c.drawImage(drawBeat(LYR1, prev, x.a - 0.001), 0, 0);
      c.save(); c.globalAlpha = e; c.translate(0, 40 * (1 - e)); c.drawImage(drawBeat(LYR2, x, t), 0, 0); c.restore();
    } else x.draw(c, t);
    vignette(c); srcLine(c, t);
    if (t > 36.0) { c.fillStyle = `rgba(0,0,0,${span(t, 36.0, 36.4)})`; c.fillRect(0, 0, 1280, 720); }
  },
  score(k) { scoreShotLab(k); },
};

// ---------- sound ----------
function scoreShotLab(k) {
  const pluck = (t, f, g = 1, pan = 0) => { k.voice(t, { type: 'triangle', f, dur: 0.7, gain: 0.09 * g, a: 0.003, verb: 0.35, pan }); k.voice(t, { f: f * 2, dur: 0.3, gain: 0.03 * g, a: 0.002, pan }); };
  const swipe = (t, pan = 0) => { k.hiss(t, { dur: 0.26, filter: 'bandpass', ff: [[0, 2000], [0.24, 5600]], q: 1.2, gain: 0.12, a: 0.08, pan }); };
  const counter = (t0, val, f0) => { let last = -1; for (let t = t0; t <= t0 + 1.1; t += 1 / 30) { const n = Math.floor(val * ez.outExpo(span(t, t0, t0 + 1.1)) / 4); if (n !== last) { k.play('tick', t, { f: f0 + n * 60, gain: 0.26, soft: true }); last = n; } } };
  padBed(k, 0.1, 36.2, { bpm: 84, gain: 0.9, cut: 1100, chords: [['A2', 'E3', 'G3', 'C4'], ['F2', 'C3', 'E3', 'A3'], ['C3', 'G3', 'B3', 'E4'], ['G2', 'D3', 'F#3', 'B3']], hats: [7.0, 13.4], kick: [28.4, 33.0] });
  // beat 1
  k.play('tick', 0.15, { f: 3400, gain: 0.3, soft: true });
  k.hiss(1.1, { dur: 0.5, filter: 'bandpass', ff: [[0, 900], [0.5, 2600]], q: 1, gain: 0.06, soft: true }); pluck(2.25, 392, 1, 0.3);
  counter(2.0, 32, 1800); swipe(4.35, -0.3);
  // beat 2 (shot, 0.5x): strike, contact, cushions
  const T = (s) => SEG.slow[0] + (s - 32.30) * 2;
  k.play('whoosh', SEG.slow[0] - 0.1, { dur: 0.5, gain: 0.35, dir: 1, top: 1800 });
  k.play('strike', T(32.45), { gain: 0.35 }); pluck(T(CONTACT), 587, 1.1, 0.1); k.play('tick', T(CONTACT), { f: 2600, gain: 0.3 });
  pluck(T(CUSH1), 330, 0.8, 0.4); pluck(T(CUSH2), 294, 0.7, 0.6);
  // beat 3
  k.play('whoosh', SEG.after[0], { dur: 0.45, gain: 0.3, dir: -1, top: 1600 });
  k.hiss(SEG.after[0] + 1.6, { dur: 0.5, filter: 'bandpass', ff: [[0, 900], [0.5, 2600]], q: 1, gain: 0.06, soft: true });
  counter(SEG.after[0] + 2.4, 96, 1600); k.play('boom', SEG.after[0] + 3.5, { gain: 0.42 });
  // beat 4
  k.play('whoosh', SEG.alt[0], { dur: 0.5, gain: 0.35, dir: 1, top: 2200 }); swipe(SEG.alt[0] + 0.5, -0.2);
  k.hiss(ALT_T[0], { color: 'pink', dur: ALT_T[1] - ALT_T[0], filter: 'bandpass', ff: [[0, 1400], [4, 300]], q: 1.2, gain: 0.035, a: 0.3, pan: [0.2, 0.6], soft: true });
  const tf = (f) => ALT_T[0] + (1 - Math.pow(1 - f, 1 / 1.9)) * (ALT_T[1] - ALT_T[0]);
  pluck(tf(ALT_F[0]), 587, 0.9, 0.1); pluck(tf(ALT_F[1]), 440, 0.8, 0.4); pluck(tf(ALT_F[2]), 392, 0.7, 0.6); pluck(ALT_T[1], 330, 0.8, 0.5);
  counter(ALT_T[1] + 0.5, 23, 1800);
  // beat 5
  k.play('whoosh', SEG.cmp[0], { dur: 0.5, gain: 0.45, dir: 1, top: 2400 });
  k.play('pop', SEG.cmp[0] + 0.25, { f: 520, gain: 0.4, pan: -0.5 }); k.play('pop', SEG.cmp[0] + 0.6, { f: 780, gain: 0.4, pan: 0.5 });
  k.play('boom', SEG.cmp[0] + 2.3, { gain: 0.45 }); swipe(SEG.cmp[0] + 2.3, 0);
  // beat 6
  k.play('whoosh', SEG.take[0], { dur: 0.5, gain: 0.35, dir: -1, top: 1800 }); swipe(SEG.take[0] + 0.95, 0);
  ['A3', 'E4', 'G4', 'C5', 'E5'].forEach((n, i) => k.voice(SEG.take[0] + 1.13 + i * 0.07, { f: n, dur: 2.0, gain: 0.045, a: 0.01, verb: 0.45, pan: (i - 2) * 0.22 }));
}
